-- merchant_action: Audit trail of merchant users' actions through the app, including object-level, store-scope and role denials and step-up refusals
CREATE TABLE merchant_action (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  merchant_id                  uuid NOT NULL,
  merchant_user_id             uuid,
  action                       varchar(64) NOT NULL,
  object_type                  varchar(40),
  object_id                    uuid,
  outcome                      varchar(40) NOT NULL CHECK (outcome IN ('SUCCEEDED', 'DENIED', 'STEP_UP_REQUIRED', 'FAILED')),
  error_code                   varchar(64),
  result_id                    uuid,
  auth_age_seconds             integer,
  acr                          varchar(64),
  ip_address                   inet,
  user_agent                   varchar(255)
);
COMMENT ON TABLE merchant_action IS 'Audit trail of merchant users'' actions through the app, including object-level, store-scope and role denials and step-up refusals';
COMMENT ON COLUMN merchant_action.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN merchant_action.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN merchant_action.created_at IS 'Creation time';
COMMENT ON COLUMN merchant_action.created_by IS 'Principal that created the row';
COMMENT ON COLUMN merchant_action.merchant_id IS 'Merchant (from the token)';
COMMENT ON COLUMN merchant_action.merchant_user_id IS 'Merchant user (from the token)';
COMMENT ON COLUMN merchant_action.action IS 'Operation (operation id of the /v1/merchant endpoint)';
COMMENT ON COLUMN merchant_action.object_type IS 'STORE, TERMINAL, SALE, TRANSACTION, REFUND, PAYMENT_LINK, SETTLEMENT, PAYOUT_CHANGE, ACCOUNT, USER, API_CLIENT, API_KEY, WEBHOOK_ENDPOINT';
COMMENT ON COLUMN merchant_action.object_id IS 'Object acted on, or the object id that was refused';
COMMENT ON COLUMN merchant_action.outcome IS 'Result';
COMMENT ON COLUMN merchant_action.error_code IS 'Problem code when not SUCCEEDED';
COMMENT ON COLUMN merchant_action.result_id IS 'Id of the record created (sale, refund, change...)';
COMMENT ON COLUMN merchant_action.auth_age_seconds IS 'Seconds since the user''s last authentication when the action ran';
COMMENT ON COLUMN merchant_action.acr IS 'Authentication context class of the token';
COMMENT ON COLUMN merchant_action.ip_address IS 'Client address (right-most X-Forwarded-For hop)';
COMMENT ON COLUMN merchant_action.user_agent IS 'Client user agent';
CREATE INDEX ix_merchant_action_tenant ON merchant_action (tenant_id, created_at);
